/**
 * 化学·身边的化学物质（模块 `chem-substance`）——人教版九年级
 * 第二单元 我们周围的空气、第四单元 自然界的水、第六单元 碳和碳的氧化物、第八单元 金属和金属材料。
 *
 * 覆盖 8 个知识点：
 *   1. 空气的组成与保护        2. 氧气的性质
 *   3. 氧气的制取              4. 水的组成与净化
 *   5. 碳单质与碳的氧化物      6. 二氧化碳的制取与性质
 *   7. 金属与金属材料          8. 金属资源的利用和保护
 *
 * 一、方程式书写口径（全库统一；条件写错或没配平，中考直接不给分）
 *   · 化学式用 Unicode 下标字符：H₂O、CO₂、Fe₃O₄、Fe₂O₃、CaCO₃、Ca(OH)₂、KMnO₄、K₂MnO₄、MnO₂、H₂SO₄、HCl；
 *   · 方程式写成可读形式，条件写在箭头上方位置：
 *     '2H₂ + O₂ —点燃→ 2H₂O'、'2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑'、'2H₂O —通电→ 2H₂↑ + O₂↑'；
 *   · 气体用 ↑、沉淀用 ↓（只在溶液中生成的气体与沉淀标注）；等号「=」用于溶液中常温进行的反应；
 *   · 条件只写「点燃／加热／高温／通电／催化剂」：不写「燃烧」代替「点燃」，不写「受热」代替「加热」，
 *     高炉炼铁写「高温」，氯酸钾制氧写「MnO₂ 作催化剂并加热」；
 *   · 每条方程式的 note 里写配平要点与易错：质量守恒 → 反应前后每一种元素的原子个数必须相等；
 *   · 相对原子质量一律取整数：H 1、C 12、N 14、O 16、P 31、S 32、Cl 35.5、K 39、Ca 40、Mn 55、Fe 56、Cu 64、Zn 65。
 *
 * 二、实验现象的标准表述（中考阅卷就按这几句话给分，写错现象等于写错答案）
 *   · 硫在氧气中燃烧：发出明亮的蓝紫色火焰，生成有刺激性气味的气体；在空气中是淡蓝色火焰；
 *   · 铁丝在氧气中燃烧：剧烈燃烧，火星四射，放出大量热，生成黑色固体 Fe₃O₄；
 *   · 木炭在氧气中燃烧：发出白光，放出热量，生成能使澄清石灰水变浑浊的气体；
 *   · 红磷燃烧：产生大量白烟（固体小颗粒，绝不能写成「白雾」）；
 *   · 镁条燃烧：发出耀眼的白光，生成白色固体；
 *   · 铜在空气中加热：红色固体逐渐变成黑色（CuO）；
 *   · 澄清石灰水变浑浊、紫色石蕊溶液变红，一律写成「……变……」，不能只写「……是……」。
 *
 * 三、安全注意事项（每组 experiments.cautions 都逐条写全，这是中考必考的操作分）
 *   · 加热固体药品制气体：试管口略向下倾斜（防冷凝水倒流炸裂试管）；实验结束先撤导管、后熄灭酒精灯（防倒吸）；
 *   · 加热高锰酸钾：试管口要塞一团棉花（防粉末进入导管）；
 *   · 铁丝在氧气中燃烧：瓶底预先放少量水或铺一层细沙（防高温熔化物溅落炸裂瓶底）；
 *   · 一氧化碳还原氧化铁：先通 CO 排尽空气再加热（防爆炸），实验后先停止加热并继续通 CO 至冷却，尾气必须处理；
 *   · 使用酒精灯：用外焰加热，不能用嘴吹灭，要用灯帽盖灭；一氧化碳有毒，相关实验必须在通风处进行。
 *
 * 四、作图与装置图的画法红线（中考实验题的核心考点，画错即错）
 *   · 加热固体制氧气：试管口略向下倾斜，导管在试管内只略伸出橡皮塞，用排水法收集时导管只伸到集气瓶口；
 *   · 向上排空气法：集气瓶正放，导管伸到接近瓶底（把瓶内空气排尽）；向下排空气法：集气瓶倒放；
 *   · 长颈漏斗的下端管口必须伸入液面以下（形成液封，防止气体从漏斗逸出）；
 *   · 用玻璃片盖住集气瓶口时，磨砂面朝下；每张图都写 alt（朗读与检索要用）。
 *
 * 五、体例：正文不使用 Markdown 加粗，中文引号统一用「」；计算题数据自洽，含杂质计算用
 * 「纯物质的质量 = 混合物的质量 × 纯度」，只有纯物质的质量才能代入化学方程式计算。
 */

