        body:
          '二氧化碳能溶于水并与水反应，所以不能用排水法收集；它的密度比空气大，所以用向上排空气法，集气瓶正放，导管伸到接近瓶底，并用玻璃片盖住瓶口。收集好以后要做两件事，先分清目的：检验是判断「这瓶气体是不是二氧化碳」，方法是把气体通入（或倒入少量）澄清石灰水，石灰水变浑浊就是二氧化碳；验满是判断「瓶里的二氧化碳满了没有」，方法是用燃着的木条放在集气瓶口，木条熄灭说明已收集满——注意木条只能放在瓶口，不能伸进瓶内。',
