        body:
          '二氧化碳的用途都来自它的性质：不能燃烧也不支持燃烧、密度比空气大，所以用来灭火（把燃着的蜡烛放在烧杯中，沿杯壁慢慢倒入二氧化碳，下面的蜡烛先熄灭、上面的后熄灭，说明它先在底部聚集）；能溶于水，所以制碳酸饮料；干冰升华吸热，用于人工降雨、食品冷藏、舞台造雾；还是光合作用的原料，可作气体肥料。空气中的二氧化碳含量升高会加剧温室效应，导致全球变暖、海平面上升。减缓的措施有：减少煤、石油等化石燃料的燃烧，开发太阳能、风能等新能源，大力植树造林。',
